#!/usr/bin/env python3
"""
Check that README.zh-CN.md stays in sync with README.md.

The Chinese file is a translation of the English one: same sections, same
entries, same order, same project names and URLs. Only the prose (titles,
descriptions) is translated.

Usage:
    python3 .github/src/check_translation_sync.py

Exit code is 0 when the two files match structurally, 1 otherwise.
"""
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
EN_PATH = os.path.join(ROOT, "README.md")
ZH_PATH = os.path.join(ROOT, "README.zh-CN.md")

H2_RE = re.compile(r"<summary>\s*<h2>(.*?)</h2>\s*</summary>")
H3_RE = re.compile(r"<h3>(.*?)</h3>")
ANCHOR_RE = re.compile(r'<a id="([^"]+)"></a>')
ENTRY_RE = re.compile(r"^- \[([^\]]+)\]\(([^)\s]+)\)")
TOC_RE = re.compile(r"^- \[([^\]]*)\]\(#([^)]+)\)")

problems = []


def parse(path):
    """Return {section: [(subsection_or_None, [(name, url), ...]), ...]}."""
    with open(path, encoding="utf-8") as fh:
        lines = fh.read().splitlines()

    sections = []
    current = None
    subsection = None
    for line in lines:
        h2 = H2_RE.search(line)
        if h2:
            current = {"title": h2.group(1), "subsections": [], "items": []}
            sections.append(current)
            subsection = None
            continue
        h3 = H3_RE.search(line)
        if h3:
            if current is not None:
                subsection = {"title": h3.group(1), "items": []}
                current["subsections"].append(subsection)
            continue
        entry = ENTRY_RE.match(line.strip())
        if not entry:
            continue
        if subsection is not None:
            subsection["items"].append((entry.group(1), entry.group(2)))
        elif current is not None:
            current["items"].append((entry.group(1), entry.group(2)))
    return sections


def toc_anchors(path):
    """Return the anchor targets listed in the table of contents."""
    anchors = []
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            match = TOC_RE.match(line.strip())
            if match:
                anchors.append(match.group(2))
    return anchors


def anchors_in_file(path):
    anchors = []
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            match = ANCHOR_RE.search(line)
            if match:
                anchors.append(match.group(1))
    return anchors


def items_of(section):
    """Flatten a section into an ordered list of (subsection_index, name, url).

    Subsection titles are translated, so they are compared by position rather
    than by text. A plain section yields subsection index None.
    """
    if section["subsections"]:
        out = []
        for index, sub in enumerate(section["subsections"]):
            for name, url in sub["items"]:
                out.append((index, name, url))
        return out
    return [(None, name, url) for name, url in section["items"]]


def slugify(title):
    """Approximate GitHub's heading anchor: lowercase, drop punctuation."""
    cleaned = re.sub(r"[^0-9a-zA-Z -]", "", title).strip().lower()
    return cleaned.replace(" ", "-")


def check_anchors(label, path, expected):
    """Check the TOC anchors of a file against its anchors.

    `expected` is a list of anchor targets. For the English file the anchors
    are generated by GitHub from the heading text, for the Chinese file they
    are declared explicitly with <a id="..."></a>.
    """
    toc = toc_anchors(path)
    if toc != expected:
        problems.append(
            "%s: TOC anchors differ: %s vs %s" % (label, ", ".join(toc), ", ".join(expected))
        )
        return
    if label == "README.zh-CN.md":
        present = anchors_in_file(path)
        missing = [anchor for anchor in toc if anchor not in present]
        if missing:
            problems.append("%s: TOC links to missing anchors: %s" % (label, ", ".join(missing)))
        extra = [anchor for anchor in present if anchor not in toc]
        if extra:
            problems.append("%s: anchors not listed in TOC: %s" % (label, ", ".join(extra)))


def main():
    if not os.path.exists(ZH_PATH):
        print("README.zh-CN.md is missing.", file=sys.stderr)
        return 1

    en = parse(EN_PATH)
    zh = parse(ZH_PATH)

    if len(en) != len(zh):
        problems.append("section count differs: %d (en) vs %d (zh)" % (len(en), len(zh)))

    for index, (en_section, zh_section) in enumerate(zip(en, zh)):
        label = "section %d" % (index + 1)
        en_items = items_of(en_section)
        zh_items = items_of(zh_section)
        if len(en_items) != len(zh_items):
            problems.append(
                "%s (%s): entry count differs: %d (en) vs %d (zh)"
                % (label, en_section["title"], len(en_items), len(zh_items))
            )
        for position, (en_item, zh_item) in enumerate(zip(en_items, zh_items)):
            if en_item[0] != zh_item[0]:
                problems.append(
                    "%s (%s): subsection differs at entry %d: %r vs %r"
                    % (label, en_section["title"], position + 1, en_item[0], zh_item[0])
                )
            if en_item[1] != zh_item[1]:
                problems.append(
                    "%s (%s): name differs at entry %d: %r vs %r"
                    % (label, en_section["title"], position + 1, en_item[1], zh_item[1])
                )
            if en_item[2] != zh_item[2]:
                problems.append(
                    "%s (%s): url differs at entry %d: %r vs %r"
                    % (label, en_section["title"], position + 1, en_item[2], zh_item[2])
                )

    # The English TOC points at anchors GitHub derives from the heading text.
    # The Chinese file declares the very same anchors explicitly, so both
    # tables of contents must list the same anchor targets.
    expected = [slugify(section["title"]) for section in en]
    check_anchors("README.md", EN_PATH, expected)
    check_anchors("README.zh-CN.md", ZH_PATH, expected)

    if problems:
        print("Translation is out of sync:")
        for problem in problems:
            print("  - %s" % problem)
        return 1

    total = sum(len(items_of(section)) for section in en)
    print("In sync: %d sections, %d entries, matching names, urls and order." % (len(en), total))
    return 0


if __name__ == "__main__":
    sys.exit(main())
